INSERT INTO `empresa` (`nm_email`,`nm_empresa`,`cd_cnpj`,`nm_link_site`,`nm_telefone`,`nm_senha`,`ic_verificado`,`nm_foto`,`ic_banido`,`ds_empresa`,`cd_verificacao`) VALUES 
 ('institutoalbatroz@gmail.com','Instituto Albatroz','05.661.298/0001-02','www.institutoalbatroz.com.br','(13)2511-2845','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Nosso trabalho é apoiar idosos. Oferecemos cuidados de saúde, companhia e atividades para promover a qualidade de vida da terceira idade.',NULL),
 ('institutoevolucao@gmail.com','Instituto Evolução','86.366.868/0001-25','www.institutoevolucao.com.br','(13)3615-4513','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Atuamos em prol do bem-estar infantil. Promovemos atividades recreativas, acesso a alimentação saudável e apoio psicológico a crianças em situações de vulnerabilidade.',NULL),
 ('providens@gmail.com','Instituto Sivis','78.999.836/0001-39','www.providens.com.br','(13)3787-2635','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Nosso objetivo é melhorar a saúde comunitária. Oferecemos serviços médicos e programas de prevenção de doenças para comunidades carentes.',NULL),
 ('saojudas@gmail.com','Igreja São Judas','51.452.475/0001-50','www.saojudas.com.br','(13) 3321-3675','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Focamos na educação inclusiva. Trabalhamos para garantir que todas as crianças, independentemente de suas habilidades, tenham acesso à educação de qualidade.\n',NULL);
INSERT INTO `empresa` (`nm_email`,`nm_empresa`,`cd_cnpj`,`nm_link_site`,`nm_telefone`,`nm_senha`,`ic_verificado`,`nm_foto`,`ic_banido`,`ds_empresa`,`cd_verificacao`) VALUES 
 ('sivis@gmail.com','Instituto Sivis','87.621.270/0001-06','www.sivis.com.br','(13)3442-3443','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Nosso compromisso é com o meio ambiente. Realizamos projetos de reflorestamento, conscientização ambiental e proteção da biodiversidade para criar um mundo mais sustentável.\n',NULL),
 ('vivabicho@gmail.com','Viva bicho','91.746.265/0001-99','www.vivabicho.com.br','(13) 2871-6177','40bd001563085fc35165329ea1ff5c5ecbdbbeef',1,,0,'Nossa organização se dedica a oferecer abrigo e apoio a pessoas sem-teto, buscando reintegrá-las à sociedade por meio de programas de moradia e empregabilidade.',NULL);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (1,'Entrega de comida para necessitados','A nossa ONG está orgulhosa de realizar um evento de entrega de comida para pessoas necessitadas. Esta iniciativa é uma expressão de nossa dedicação em fornecer apoio alimentar àqueles que enfrentam desafios econômicos e garantir que ninguém na nossa comunidade passe fome. Com a ajuda de voluntários generosos e doações, estamos comprometidos em oferecer refeições nutritivas e reconfortantes, aliviando as dificuldades que muitos enfrentam diariamente. Juntos, estamos fazendo a diferença ao garantir que as pessoas tenham acesso a alimentos essenciais e uma mensagem de solidariedade em tempos difíceis.','Rua Brasilia, 41, Cubatão','2023-12-23 14:00:00','2023-12-23 20:00:00','2023-12-20 23:59:59',,'cagg@gmail.com',2,2),
 (2,'Distribuição de roupas de frio para moradores de rua','Junte-se a nós em um dia de calor humano e generosidade, onde a comunidade se une para \n conforto e dignidade aos moradores de rua durante a estação mais fria do ano. O evento é mais do que apenas a distribuição de\n roupas de frio; é um gesto de compaixão que aquece os corações e corpos daqueles que mais necessitam.','Avenida Brasil, 24, Cubatão','2023-12-28 12:00:00','2023-12-28 17:00:00','2023-12-25 23:59:59',,'saojudas@gmail.com',6,2),
 (3,'Resgate de animais de rua','Estamos comprometidos em realizar um evento de resgate de animais de rua. Nossa ONG se dedica a fornecer cuidados e encontrar lares amorosos para animais abandonados. Com a ajuda de voluntários e parceiros, trabalhamos para oferecer uma segunda chance a essas criaturas, promovendo a conscientização sobre a proteção animal.','Rua José dos campos, 33, Santos','2023-12-23 15:00:00','2023-12-23 18:00:00','2023-12-20 23:59:59',,'caminhopet@gmail.com',13,8),
 (4,'Aula de reforço para crianças','A nossa ONG está entusiasmada em promover um evento de aulas para crianças necessitadas. Este projeto visa proporcionar acesso à educação de qualidade para as crianças em situação de vulnerabilidade, capacitando-as com conhecimento e habilidades essenciais para um futuro mais promissor. Nossos dedicados voluntários e parceiros estão comprometidos em criar um ambiente de aprendizado acolhedor e inclusivo, visando não apenas ao desenvolvimento acadêmico, mas também ao fortalecimento das perspectivas de vida dessas crianças. Juntos, estamos construindo um caminho para um amanhã mais brilhante e equitativo.','Avenida Aparecida, 101, Praia Grande','2023-12-26 13:00:00','2023-12-26 18:00:00','2023-12-22 23:59:59',,'childfund@gmail.com',7,7),
 (5,'Recolhimento de lixo nas ruas','A nossa ONG está animada para realizar um evento de limpeza nas ruas da nossa comunidade, visando criar um ambiente mais limpo e conscientizar sobre a importância da preservação ambiental. Mobilizaremos voluntários, forneceremos equipamentos de segurança e promoveremos a união entre os moradores, acreditando que nossa ação pode inspirar práticas sustentáveis e cuidados com o planeta. Junte-se a nós nesta iniciativa para um futuro mais limpo e saudável.','Rua Floriano Peixoto, 22, São Vicente','2023-12-23 14:00:00','2023-12-23 18:00:00','2023-12-21 23:59:59',,'saojudas@gmail.com',10,9);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (6,'Trabalho voluntário em asilo','Organizar um evento de trabalho voluntário em um asilo é uma oportunidade emocionante para a nossa ONG. Estamos comprometidos em proporcionar momentos de alegria e apoio a idosos que muitas vezes se sentem solitários. Com a ajuda de voluntários dedicados, pretendemos criar um ambiente acolhedor e interativo, compartilhando histórias, atividades e afeto, para que os residentes se sintam valorizados e amados. Juntos, estamos construindo laços intergeracionais e promovendo uma sensação de comunidade que enriquece as vidas de todos envolvidos.','Rua Maria do Carmo, 43, São Vicente','2023-12-27 15:00:00','2023-12-27 18:00:00','2023-12-20 23:59:59',,'saojudas@gmail.com',9,9),
 (7,'Limpeza da praia','Estamos entusiasmados em realizar um evento de limpeza de lixo nas praias para proteger nossos ecossistemas costeiros e conscientizar sobre a importância da conservação. Com voluntários dedicados, removemos resíduos prejudiciais e promovemos praias limpas e seguras.','Ponta da praia, Santos','2023-12-26 14:00:00','2023-12-26 18:00:00','2023-12-25 23:59:59',,'cagg@gmail.com',10,8);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (8,'Visita em orfanato','O evento de voluntários é uma iniciativa calorosa e solidária, onde pessoas de corações generosos se reúnem para fazer a diferença na vida das crianças e adolescentes em um abrigo. Com empatia e dedicação, os voluntários oferecem seu tempo e carinho, proporcionando momentos de alegria, aprendizado e apoio emocional. Juntos, eles criam um ambiente acolhedor e inspirador, reforçando a importância da comunidade e da solidariedade para um futuro mais brilhante para esses jovens.','Pedro Lessa, 105, Santos','2023-12-20 16:00:00','2023-12-20 19:00:00','2023-12-18 23:59:59',,'cagg@gmail.com',4,8),
 (9,'Ajuda para abrigo de animais','O evento de voluntários é uma demonstração de amor incondicional pelos animais abandonados. Nele, pessoas apaixonadas se unem para oferecer cuidado e conforto a cães e gatos que precisam desesperadamente de um lar. Com dedicação e compaixão, os voluntários alimentam, cuidam da higiene e proporcionam carinho a esses animais, criando um ambiente de esperança e promovendo a adoção responsável. Este evento é um lembrete poderoso de como a bondade humana pode fazer a diferença nas vidas dos nossos amigos de quatro patas.','Embaré, 271, Santos','2023-12-15 15:00:00','2023-12-15 19:00:00','2023-12-12 23:59:59',,'cagg@gmail.com',13,8);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (10,'Psicólogos Solidários','O evento \"Psicólogos Solidários\" é uma iniciativa inspiradora que reúne psicólogos voluntários com o objetivo de oferecer apoio emocional e orientação a pessoas em situações de necessidade. Durante este evento, profissionais qualificados disponibilizam seu tempo e experiência para ouvir, aconselhar e proporcionar um ambiente acolhedor para aqueles que enfrentam desafios emocionais. Este encontro promove o bem-estar psicológico, fornecendo suporte compassivo e empático a indivíduos que podem estar lidando com traumas, ansiedade, depressão ou outras dificuldades emocionais. É um exemplo brilhante de como a psicologia pode ser usada para fazer a diferença positiva nas vidas das pessoas em momentos difíceis.','Avenida Brasil, 156, Cubatão','2023-12-16 13:00:00','2023-12-16 18:00:00','2023-12-13 23:59:59',,'amigosdobem@gmail.com',2,2),
 (11,'Aulão de Redação','O evento \"Professores Voluntários de Português\" reúne educadores que auxiliam adolescentes a melhorar suas habilidades de redação, promovendo desenvolvimento acadêmico e confiança na expressão escrita. É uma iniciativa inspiradora de voluntariado educacional.','Pedro Lessa, 204, Santos','2023-12-17 12:30:00','2023-12-17 17:00:00','2023-12-14 23:59:59',,'institutoevolucao@gmail.com',7,8);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (12,'Limpeza da praça da independência ','Neste evento iremos limpar e retirar todo o lixo deixado na praça da independência, com o fim de deixar o local mais agradavel.','Praça da independência, Cubatão','2023-12-17 14:00:00','2023-12-17 18:00:00','2023-12-15 23:59:59',,'sivis@gmail.com',10,2),
 (13,'Evento de pediatria','Estamos promovendo um evento de pediatria totalmente gratuito com o fim de ajudar famílias necessitadas que precisam de ajuda profissional.','Rua São Tomé de Aquino, 345, São Vicente','2023-12-18 12:00:00','2023-12-18 18:00:00','2023-12-15 23:59:59',,'saojudas@gmail.com',4,9);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (14,'Castração de animais gratuita','Neste evento temos a intenção de prover a castração gratuita dos animais de pessoas que não tem condição de pagar um veterinario particular.','Rua Aristóteles, 212, Praia Grande','2023-12-18 14:00:00','2023-12-18 19:00:00','2023-12-15 23:59:59',,'providens@gmail.com',13,7),
 (15,'Sopão para moradores de rua','A ideia do evento é cozinharmos um sopão com a ajuda de alguns voluntários e em seguida distribuirmos a comida que foi feita para moradores de rua em estado de necessidade.','Avenida Maria do Carmo, 125, São Vicente','2023-12-19 18:00:00','2023-12-19 21:00:00','2023-12-15 23:59:59',,'providens@gmail.com',2,9);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (16,'Distribuição de livros para crianças','Queremos incentivar o consumo de livros na parte da infância e da adolescência, assim ajudando no aprendizado dos mesmos, e mostrando um mundo totalmente novo para eles, que estimule a sua criatividade e imaginação.','Avenida Brasil, 246, Cubatão','2023-12-19 14:00:00','2023-12-19 18:00:00','2023-12-16 23:59:59',,'institutoalbatroz@gmail.com',7,2),
 (17,'Adoção de animais','Estamos provendo este evento para a adoção de animais resgatados em situação de rua, e contamos com a ajuda de voluntários que tenham a vontade de nos ajudar a organizar o evento e cuidar dos animais durante o mesmo.','Rua Maria Cristina, 172,  Cubatão','2023-12-19 14:00:00','2023-12-19 19:00:00','2023-12-16 23:59:59',,'vivabicho@gmail.com',13,2),
 (18,'Evento de limpeza em escola','Estamos a procura de voluntarios  que estejam com vontade de ajudar a promover a limpeza de uma das escolas da cidade, gerando assim um ambiente de melhor infraestrutura para os alunos e profissionais que ali convivem.','Avenida São José dos Campos, 411, Santos','2023-12-19 13:00:00','2023-12-19 18:00:00','2023-12-16 23:59:59',,'institutoevolucao@gmail.com',4,8);
INSERT INTO `evento` (`cd_evento`,`nm_evento`,`ds_evento`,`ds_endereco`,`dt_inicio`,`dt_fim`,`dt_limite_inscricao`,`nm_imagem`,`nm_email`,`cd_categoria_evento`,`cd_cidade`) VALUES 
 (19,'Evento de música para crianças ','Estaremos realizando um evento para apresentar o mundo música para as crianças e adolescentes de uma escola. Desejamos despertar nelas a vontade de tocar um instrumento e assim incentivar a prática da cultura.','Rua São Pedro, 182, Santos','2023-12-17 12:30:00','2023-12-17 17:00:00','2023-12-14 23:59:59',,'childfund@gmail.com',5,8),
 (20,'DIstribuição de comida para necessitados','Precisamos de pessoas que estejam dispostas a nos ajudar na realização de um evento de entrega de marmitas para pessoas em estado de necessidade nos bairos de Cubatão.','Rua Maria Graziela, 193, Cubatão','2023-10-19 18:00:00','2023-10-19 21:00:00','2023-10-15 23:59:59',,'cagg@gmail.com',2,2),
 (21,'Limpeza de orfanato','Estamos procurando pessoas que tenham vontade de nos ajudar a limpar um orfanato que está precisando de ajuda em Cubatão.','Rua Brasilia, 201, Cubatão','2023-10-20 14:00:00','2023-10-20 18:00:00','2023-10-15 23:59:59',,'cagg@gmail.com',10,2);
