 (34,7,'2023-12-26 14:00:00','2023-12-26 18:00:00',8,'Estamos a procura de pessoas que nos ajudem com a limpeza do local.'),
 (35,18,'2023-12-19 13:00:00','2023-12-19 18:00:00',5,'Estamos a procura de pessoas que queiram deixar a escola um ambiente mais limpo e saudável para os estudantes e profissionais que ali se encontram.'),
 (36,19,'2023-12-17 12:30:00','2023-12-17 17:00:00',2,'Precisamos que nos ajudem a organizar o evento.'),
 (37,19,'2023-12-17 12:30:00','2023-12-17 17:00:00',5,'Precisamos de músicos e professores de música que estejam dispostos a mostrar para as pessoas presentes a arte da música.'),
 (38,20,'2023-10-19 18:00:00','2023-10-19 21:00:00',0,'Estamos procurando pessoas que nos ajudem a entregar as marmitas para os moradores de rua e pessoas necessitadas.'),
