INSERT INTO `usuario` (`nm_email`,`nm_usuario`,`nm_senha`,`nm_foto_perfil`,`ic_banido`,`cd_cpf`,`cd_verificacao`,`nm_foto_documento`,`cd_rg`,`ic_verificado`,`cd_tipo_usuario`,`ds_usuario`) VALUES 
 ('ana.julia@gmail.com','Ana Julia','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'105.097.261-94','6574',NULL,'282670804',1,1,'Sou uma pessoa que tem vontade de ajudar os mais necessitados e estou a procura de eventos que tenham o mesmo objetivo.'),
 ('antonio.matos@gmail.com','Antonio Matos','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'332.128.478-24','3647',NULL,'478528863',1,1,'Minha paixão é a saúde global. Como voluntário, viajo para áreas carentes, oferecendo serviços médicos essenciais e conscientização sobre práticas de higiene e prevenção de doenças.\n');
INSERT INTO `usuario` (`nm_email`,`nm_usuario`,`nm_senha`,`nm_foto_perfil`,`ic_banido`,`cd_cpf`,`cd_verificacao`,`nm_foto_documento`,`cd_rg`,`ic_verificado`,`cd_tipo_usuario`,`ds_usuario`) VALUES 
 ('cesar.ribeiro@gmail.com','César Ribeiro','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'867.575.168-02','1097',NULL,'474394529',1,1,'Como voluntário de refúgio, ofereço suporte emocional e integração a refugiados que chegam à minha comunidade, ajudando-os a se adaptarem e a reconstruírem suas vidas.'),
 ('gabriel.lima@gmail.com','Gabriel Lima','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'582.017.928-58','1234',NULL,'454408602',1,1,'Meu propósito é combater a fome. Como voluntário em bancos de alimentos, ajudo a arrecadar, armazenar e distribuir alimentos para famílias necessitadas em nossa região.\n'),
 ('jadeyume@gmail.com','Jade Masuda','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'433.234.358-18','123',,'15.580.139-9',0,1,NULL),
 ('joao.gabriel@gmail.com','João Gabriel','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'032.536.848-14','7654',NULL,'145674836',1,1,'Sou um entusiasta do esporte e, como voluntário, treino jovens atletas em minha comunidade, incentivando-os a adotar valores de trabalho em equipe e determinação.');
INSERT INTO `usuario` (`nm_email`,`nm_usuario`,`nm_senha`,`nm_foto_perfil`,`ic_banido`,`cd_cpf`,`cd_verificacao`,`nm_foto_documento`,`cd_rg`,`ic_verificado`,`cd_tipo_usuario`,`ds_usuario`) VALUES 
 ('joao.vitor@gmail.com','João Vitor dos Santos','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'338.441.328-80','5973',NULL,'335154591',1,1,'Como ex-professor, encontrei minha vocação como voluntário, oferecendo aulas de matemática e ciências a estudantes de escolas locais, buscando inspirar o amor pelo aprendizado.'),
 ('julia.silva@gmail.com','Julia Silva','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'227.489.021-81','1599',NULL,'105978954',1,1,'Meu compromisso como voluntária é com a inclusão. Trabalho com crianças com deficiências, proporcionando um ambiente acolhedor onde podem aprender e crescer, celebrando suas diferenças.');
INSERT INTO `usuario` (`nm_email`,`nm_usuario`,`nm_senha`,`nm_foto_perfil`,`ic_banido`,`cd_cpf`,`cd_verificacao`,`nm_foto_documento`,`cd_rg`,`ic_verificado`,`cd_tipo_usuario`,`ds_usuario`) VALUES 
 ('julio.santos@gmail.com','Julio Santos','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'446.940.178-10','8574',NULL,'317757660',1,1,'Como voluntário, minha missão é preservar o meio ambiente, dedicando meu tempo a projetos de reflorestamento e educação ambiental para conscientizar as pessoas sobre a importância da natureza.'),
 ('mariana.barbosa@gmail.com','Mariana Barbosa Cabral','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'277.621.918-01','1235',NULL,'185212487',1,1,'Estou comprometida com a educação de qualidade. Como voluntária, atuo em programas de tutoria, auxiliando alunos a melhorar seu desempenho escolar e alcançar seus objetivos acadêmicos.'),
 ('matheus.neves@gmail.com','Matheus Paz Neves','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'455.171.228-09','0975',NULL,'152776163',1,1,'Meu voluntariado está centrado na conscientização sobre saúde mental. Trabalho em grupos de apoio, oferecendo um espaço seguro para homens compartilharem suas experiências e lidarem com desafios emocionais.'),
 ('pedro.silva@gmail.com','Pedro Silva Barros','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'628.684.068-07','1098',NULL,'427338360',1,1,'Como voluntário, estou comprometido com a educação de jovens em situação de risco. Ajudo a organizar programas de mentoria que capacitam adolescentes a alcançar seu potencial e evitar caminhos negativos.');
INSERT INTO `usuario` (`nm_email`,`nm_usuario`,`nm_senha`,`nm_foto_perfil`,`ic_banido`,`cd_cpf`,`cd_verificacao`,`nm_foto_documento`,`cd_rg`,`ic_verificado`,`cd_tipo_usuario`,`ds_usuario`) VALUES 
 ('rodrigo.sampaio@gmail.com','Rodrigo Sampaio','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'374.584.058-56','1256',NULL,'416140725',1,1,'Minha paixão é a preservação do patrimônio histórico. Como voluntário, dedico meu tempo a restaurar edifícios antigos e monumentos, garantindo que nossa herança cultural seja preservada para as futuras gerações.'),
 ('sofia.ribeiro@gmail.com','Sofia Ribeiro','40bd001563085fc35165329ea1ff5c5ecbdbbeef',,0,'551.163.143-40','9834',NULL,'256445370',1,1,'Sou apaixonada por ajudar os outros e, como voluntária, estou empenhada em fazer a diferença na vida das pessoas, seja apoiando comunidades carentes ou auxiliando crianças em situações de vulnerabilidade.');
